class MainActivity : AppCompatActivity() {
    private val bg=Color.rgb(13,13,14); private val surface=Color.rgb(27,27,29); private val surface2=Color.rgb(35,35,38); private val orange=Color.rgb(255,122,0); private val white=Color.rgb(245,245,247); private val muted=Color.rgb(150,150,155)
    private val prefs by lazy { getSharedPreferences("radio", MODE_PRIVATE) }; private val executor=Executors.newSingleThreadExecutor(); private val handler=Handler(Looper.getMainLooper())
    private val taglines=listOf("Keyfinin Frekansı.","Keyfin Neyi Çekerse.","Ruh Haline Bir Frekans.","Her Moda Bir Radyo.","Bir Frekans, Bin Keyif.")
    private var taglineIndex=0; private var stations=emptyList<Station>(); private var currentIndex=-1; private var selectedNav=0; private var controller:MediaController?=null; private var controllerFuture:ListenableFuture<MediaController>?=null; private var nowPlaying=""
    private lateinit var adapter:StationAdapter; private lateinit var homeScroll:ScrollView; private lateinit var homeContainer:LinearLayout; private lateinit var stationList:RecyclerView; private lateinit var search:EditText; private lateinit var title:TextView; private lateinit var status:TextView; private lateinit var liveBadge:TextView; private lateinit var tagline:TextView; private lateinit var play:ImageButton; private lateinit var spectrum:AudioSpectrumView; private lateinit var miniLogo:StationArtworkView
    private val navCards=mutableListOf<View>(); private val navIcons=mutableListOf<ImageView>(); private val navLabels=mutableListOf<TextView>()
    private val taglineRunnable=object:Runnable{override fun run(){if(isFinishing||isDestroyed)return;tagline.animate().alpha(0f).setDuration(160).withEndAction{if(isFinishing||isDestroyed)return@withEndAction;taglineIndex=(taglineIndex+1)%taglines.size;tagline.text=taglines[taglineIndex];tagline.animate().alpha(1f).setDuration(240).start()}.start();handler.postDelayed(this,3600L)}}

    override fun onCreate(savedInstanceState:Bundle?){super.onCreate(savedInstanceState);window.statusBarColor=bg;window.navigationBarColor=bg;setContentView(buildUi());handler.postDelayed(taglineRunnable,1800L);onBackPressedDispatcher.addCallback(this,object:OnBackPressedCallback(true){override fun handleOnBackPressed(){if(search.visibility==View.VISIBLE){search.visibility=View.GONE;search.clearFocus()}else if(selectedNav!=0)handleNav(0)else showExitDialog()}});connectPlayer();loadStations()}

    private fun buildUi():View{
        val root=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setBackgroundColor(bg)}
        val top=LinearLayout(this).apply{gravity=Gravity.CENTER_VERTICAL;setPadding(d(10),d(7),d(10),d(6))}
        val brandBox=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER_VERTICAL;layoutParams=LinearLayout.LayoutParams(0,d(62),1f);isClickable=true;setOnClickListener{tap(this)}}
        val brand=ImageView(this).apply{setImageResource(R.drawable.keyfe_keder_brand);scaleType=ImageView.ScaleType.CENTER_CROP;clipToOutline=true;background=rounded(Color.rgb(18,18,19),12);contentDescription="Keyfe Keder Radyo"}
        brandBox.addView(brand,LinearLayout.LayoutParams(d(48),d(48)).apply{rightMargin=d(10)})
        val brandText=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;gravity=Gravity.CENTER_VERTICAL}
        val brandTitle=TextView(this).apply{text="KEYFE KEDER RADYO";textSize=17f;setTextColor(white);setTypeface(typeface,android.graphics.Typeface.BOLD);letterSpacing=.03f;maxLines=1}
        tagline=TextView(this).apply{text=taglines[0];textSize=10.5f;setTextColor(orange);maxLines=1;alpha=.9f};brandText.addView(brandTitle);brandText.addView(tagline);brandBox.addView(brandText,LinearLayout.LayoutParams(0,-2,1f))
        val tools=LinearLayout(this).apply{gravity=Gravity.CENTER_VERTICAL};val searchButton=iconButton(R.drawable.ic_search).apply{contentDescription="Radyo ara"}
        liveBadge=TextView(this).apply{text="RADYO";textSize=10f;setTextColor(muted);gravity=Gravity.CENTER;background=rounded(Color.rgb(28,24,21),14);layoutParams=LinearLayout.LayoutParams(d(64),d(30)).apply{leftMargin=d(4)}}
        tools.addView(searchButton);tools.addView(liveBadge);top.addView(brandBox);top.addView(tools);root.addView(top)
        search=EditText(this).apply{hint="Radyo ara...";setTextColor(white);setHintTextColor(muted);setSingleLine(true);setPadding(d(16),0,d(16),0);background=rounded(surface,18);visibility=View.GONE;addTextChangedListener(object:android.text.TextWatcher{override fun beforeTextChanged(s:CharSequence?,start:Int,count:Int,after:Int)=Unit;override fun onTextChanged(s:CharSequence?,start:Int,before:Int,count:Int){filter(s?.toString().orEmpty())};override fun afterTextChanged(s:android.text.Editable?)=Unit})}
        root.addView(search,LinearLayout.LayoutParams(-1,d(50)).apply{setMargins(d(10),0,d(10),d(8))});searchButton.setOnClickListener{tap(it);search.visibility=if(search.visibility==View.VISIBLE)View.GONE else View.VISIBLE;if(search.visibility==View.VISIBLE)search.requestFocus()}
        homeScroll=ScrollView(this).apply{overScrollMode=View.OVER_SCROLL_NEVER;isFillViewport=true;setPadding(d(10),0,d(10),d(8))};homeContainer=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(0,d(4),0,d(18))};homeScroll.addView(homeContainer,ViewGroup.LayoutParams(-1,-1));root.addView(homeScroll,LinearLayout.LayoutParams(-1,0,1f))
        stationList=RecyclerView(this).apply{layoutManager=GridLayoutManager(this@MainActivity,2);overScrollMode=View.OVER_SCROLL_NEVER;setPadding(d(5),0,d(5),d(8));clipToPadding=false;visibility=View.GONE};adapter=StationAdapter({play(it)},{isFavorite(it)},{toggleFavorite(it)});stationList.adapter=adapter;root.addView(stationList,LinearLayout.LayoutParams(-1,0,1f))
        root.addView(buildMiniPlayer(),LinearLayout.LayoutParams(-1,d(76)).apply{setMargins(d(8),d(4),d(8),d(6))});root.addView(buildBottomNav(),LinearLayout.LayoutParams(-1,d(68)));buildHome();return root
    }

    private fun buildBottomNav():View{val nav=LinearLayout(this).apply{gravity=Gravity.CENTER;setPadding(d(6),d(5),d(6),d(6));setBackgroundColor(surface)};val items=listOf(R.drawable.ic_home to "Ana Sayfa",R.drawable.ic_radio to "Radyolar",R.drawable.ic_explore to "Keşfet",R.drawable.ic_heart to "Favoriler",R.drawable.ic_settings to "Ayarlar");items.forEachIndexed{i,p->val card=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;gravity=Gravity.CENTER;setPadding(d(4),d(3),d(4),d(3));isClickable=true;isFocusable=true;layoutParams=LinearLayout.LayoutParams(0,-1,1f).apply{leftMargin=d(2);rightMargin=d(2)};background=rounded(if(i==0)Color.rgb(44,31,23)else Color.TRANSPARENT,16);setOnClickListener{tap(this);handleNav(i)}};val icon=ImageView(this).apply{setImageResource(p.first);setColorFilter(if(i==0)orange else muted);layoutParams=LinearLayout.LayoutParams(d(22),d(24))};val label=TextView(this).apply{text=p.second;textSize=10.5f;setTextColor(if(i==0)orange else muted);gravity=Gravity.CENTER};card.addView(icon);card.addView(label);nav.addView(card);navCards.add(card);navIcons.add(icon);navLabels.add(label)};return nav}
    private fun selectNav(index:Int){selectedNav=index;navCards.forEachIndexed{i,card->val active=i==index;card.background=rounded(if(active)Color.rgb(44,31,23)else Color.TRANSPARENT,16);navIcons[i].setColorFilter(if(active)orange else muted);navLabels[i].setTextColor(if(active)orange else muted);card.alpha=if(active)1f else .86f}}
    private fun handleNav(index:Int){selectNav(index);search.visibility=View.GONE;search.clearFocus();when(index){0->{stationList.visibility=View.GONE;homeScroll.visibility=View.VISIBLE;buildHome();homeScroll.scrollTo(0,0)};1->showRadios(stations);2->{stationList.visibility=View.GONE;homeScroll.visibility=View.VISIBLE;buildDiscover();homeScroll.scrollTo(0,0)};3->showRadios(stations.filter{isFavorite(it)});4->showSettings()}}
    private fun showRadios(list:List<Station>){homeScroll.visibility=View.GONE;stationList.visibility=View.VISIBLE;adapter.submitList(list);stationList.scrollToPosition(0)}

    private fun buildHome(){homeContainer.removeAllViews();homeContainer.addView(TextView(this).apply{text="Bugün ne dinlemek istiyorsun?";textSize=24f;setTextColor(white);setTypeface(typeface,android.graphics.Typeface.BOLD);setPadding(d(4),d(8),d(4),0)});homeContainer.addView(TextView(this).apply{text="Ruh haline bir frekans seç.";textSize=13f;setTextColor(muted);setPadding(d(4),d(2),d(4),d(12))});homeContainer.addView(buildPickerCard());val moods=listOf("🌙 Sakin" to listOf("chill","lounge","jazz","classical","easy"),"❤️ Arabesk" to listOf("arabesk","fantazi","damar"),"🔥 Pop" to listOf("pop","hit","top"),"🎸 Rock" to listOf("rock","metal","alternative"),"🕺 90'lar" to listOf("90","nostalgia","retro"));val moodScroll=android.widget.HorizontalScrollView(this).apply{isHorizontalScrollBarEnabled=false;overScrollMode=View.OVER_SCROLL_NEVER};val moodRow=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL};moods.forEach{(label,tokens)->val chip=TextView(this).apply{text=label;textSize=12f;setTextColor(white);gravity=Gravity.CENTER;setPadding(d(15),0,d(15),0);background=rounded(surface2,20);isClickable=true;setOnClickListener{tap(this);val filtered=stations.filter{st->val h="${st.genre} ${st.name} ${st.song}";tokens.any{t->h.contains(t,true)}};showRadios(filtered);selectNav(1)}};moodRow.addView(chip,LinearLayout.LayoutParams(-2,d(40)).apply{rightMargin=d(8)})};moodScroll.addView(moodRow,ViewGroup.LayoutParams(-2,d(46)));homeContainer.addView(moodScroll,LinearLayout.LayoutParams(-1,d(50)));addSection("Son Dinlediklerin",historyStations(),"Henüz bir radyo dinlemedin.");addSection("Favorilerin",stations.filter{isFavorite(it)}.take(10),"Henüz favorin yok. Bir radyoya kalp bırak.");addSection("Keyfe Keder Seçtik",stations.filter{it.genre.isNotBlank()}.take(10),"Sana birkaç frekans seçiyoruz.");homeContainer.addView(TextView(this).apply{text="Tüm Radyolar  →";textSize=14f;setTextColor(orange);gravity=Gravity.CENTER;isClickable=true;setOnClickListener{tap(this);showRadios(stations);selectNav(1)}},LinearLayout.LayoutParams(-1,d(52)))}

    private fun buildPickerCard():View{val card=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER_VERTICAL;setPadding(d(14),d(12),d(10),d(12));background=GradientDrawable().apply{setColor(Color.rgb(39,27,20));cornerRadius=d(24).toFloat();setStroke(d(1),Color.rgb(105,58,28))};isClickable=true;isFocusable=true;setOnClickListener{tap(this);pickForMe()}};val icon=TextView(this).apply{text="🎲";textSize=30f;gravity=Gravity.CENTER};card.addView(icon,LinearLayout.LayoutParams(d(58),d(62)));val info=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;gravity=Gravity.CENTER_VERTICAL;layoutParams=LinearLayout.LayoutParams(0,-2,1f)};info.addView(TextView(this).apply{text="KEYFİME BIRAK";textSize=16f;setTextColor(white);setTypeface(typeface,android.graphics.Typeface.BOLD);letterSpacing=.04f});info.addView(TextView(this).apply{text="Bugün seçimi sana yaptırmıyorum.";textSize=11f;setTextColor(Color.rgb(204,166,136));maxLines=1});card.addView(info);card.addView(TextView(this).apply{text="›";textSize=30f;setTextColor(orange);gravity=Gravity.CENTER},LinearLayout.LayoutParams(d(30),d(56)));return card}

    private fun pickForMe(){if(isFinishing||isDestroyed)return;if(stations.isEmpty()){android.widget.Toast.makeText(this,"Radyolar henüz yükleniyor.",android.widget.Toast.LENGTH_SHORT).show();return};val history=prefs.getString("history","").orEmpty().split("|").filter{it.isNotBlank()}.toSet();val recent=history.take(4).toSet();val favorites=stations.filter{isFavorite(it)};val pool=stations.filter{it.resolvedUrl !in recent}.ifEmpty{stations};if(pool.isEmpty())return;val weighted=pool.map{st->var score=1;if(isFavorite(st))score+=7;if(st.genre.isNotBlank())score+=2;if(st.resolvedUrl !in history)score+=4;if(currentIndex>=0&&stations.getOrNull(currentIndex)?.resolvedUrl==st.resolvedUrl)score-=8;st to score.coerceAtLeast(1)};val total=weighted.sumOf{it.second};var roll=(1..total).random();var chosen=weighted.last().first;for((st,score)in weighted){roll-=score;if(roll<=0){chosen=st;break}};showPickResult(chosen,favorites.isNotEmpty())}

    private fun showPickResult(station:Station,hasFavorites:Boolean){if(isFinishing||isDestroyed)return;val message=buildString{append(station.name);val meta=listOf(station.genre,station.country).filter{it.isNotBlank()}.joinToString(" • ");if(meta.isNotBlank())append("\n\n").append(meta);append("\n\n");append(if(isFavorite(station))"Favorilerinden sana bir seçim." else if(hasFavorites)"Favorilerine farklı bir alternatif." else "Daha önce sıkmadığın bir frekans.")};val dialog=AlertDialog.Builder(this).setTitle("BUGÜNÜN FREKANSI").setMessage(message).setNegativeButton("Kapat",null).setPositiveButton("ŞİMDİ DİNLE",null).setNeutralButton("BAŞKA BİR TANE",null).create();dialog.setOnShowListener{dialog.getButton(android.content.DialogInterface.BUTTON_POSITIVE)?.setTextColor(orange);dialog.getButton(android.content.DialogInterface.BUTTON_NEGATIVE)?.setTextColor(muted);dialog.getButton(android.content.DialogInterface.BUTTON_NEUTRAL)?.setTextColor(muted);dialog.getButton(android.content.DialogInterface.BUTTON_POSITIVE)?.setOnClickListener{if(!isFinishing&&!isDestroyed){dialog.dismiss();play(station)}};dialog.getButton(android.content.DialogInterface.BUTTON_NEUTRAL)?.setOnClickListener{if(!isFinishing&&!isDestroyed){dialog.dismiss();handler.postDelayed({if(!isFinishing&&!isDestroyed)pickForMe()},180L)}}};dialog.setOnDismissListener{handler.removeCallbacksAndMessages(null)};dialog.show()}

    private fun buildDiscover(){buildHome();(homeContainer.getChildAt(0)as?TextView)?.text="Keşfet";(homeContainer.getChildAt(1)as?TextView)?.text="Bugün hangi frekanstasın?"}
    private fun addSection(name:String,list:List<Station>,empty:String){homeContainer.addView(TextView(this).apply{text=name;textSize=18f;setTextColor(white);setTypeface(typeface,android.graphics.Typeface.BOLD);setPadding(d(4),d(18),d(4),d(8))});if(list.isEmpty()){homeContainer.addView(TextView(this).apply{text=empty;textSize=12f;setTextColor(muted);setPadding(d(8),0,d(8),0)},LinearLayout.LayoutParams(-1,d(42)));return};val scroll=android.widget.HorizontalScrollView(this).apply{isHorizontalScrollBarEnabled=false;overScrollMode=View.OVER_SCROLL_NEVER};val row=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL};list.forEach{st->row.addView(homeCard(st),LinearLayout.LayoutParams(d(154),d(176)).apply{rightMargin=d(10)})};scroll.addView(row,ViewGroup.LayoutParams(-2,d(180)));homeContainer.addView(scroll,LinearLayout.LayoutParams(-1,d(184)))}
    private fun homeCard(station:Station):View{val card=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(d(10),d(10),d(10),d(10));background=rounded(surface2,22);isClickable=true;isFocusable=true;setOnClickListener{tap(this);play(station)}};val image=StationArtworkView(this).apply{background=rounded(Color.rgb(18,18,19),18);clipToOutline=true;contentDescription=station.name;bind(station.name,station.genre)};card.addView(image,LinearLayout.LayoutParams(-1,d(106)));card.addView(TextView(this).apply{text=station.name;textSize=13f;setTextColor(white);setTypeface(typeface,android.graphics.Typeface.BOLD);maxLines=1;ellipsize=android.text.TextUtils.TruncateAt.END;setPadding(d(2),d(7),d(2),0)});card.addView(TextView(this).apply{text=listOf(station.genre,station.country).filter{it.isNotBlank()}.joinToString(" • ").ifBlank{"Canlı radyo"};textSize=9.5f;setTextColor(muted);maxLines=1;ellipsize=android.text.TextUtils.TruncateAt.END});return card}

    private fun buildMiniPlayer():View{val row=LinearLayout(this).apply{gravity=Gravity.CENTER_VERTICAL;setPadding(d(10),d(7),d(8),d(7));background=rounded(surface2,24);elevation=d(8).toFloat();setOnClickListener{if(!isFinishing&&!isDestroyed)showFullPlayer()}};miniLogo=StationArtworkView(this).apply{clipToOutline=true;layoutParams=LinearLayout.LayoutParams(d(50),d(50)).apply{rightMargin=d(9)};bind("RADYO","")};val info=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;gravity=Gravity.CENTER_VERTICAL;layoutParams=LinearLayout.LayoutParams(0,-2,1f)};title=TextView(this).apply{text="Bir radyo seç";textSize=14f;setTextColor(white);maxLines=1};status=TextView(this).apply{text="Hazır";textSize=11f;setTextColor(muted);maxLines=1};spectrum=AudioSpectrumView(this).apply{layoutParams=LinearLayout.LayoutParams(-1,d(16))};info.addView(title);info.addView(status);info.addView(spectrum);val prev=iconButton(R.drawable.ic_prev);play=iconButton(R.drawable.ic_play);val next=iconButton(R.drawable.ic_next);prev.setOnClickListener{tap(it);playRelative(-1)};play.setOnClickListener{tap(it);togglePlay()};next.setOnClickListener{tap(it);playRelative(1)};row.addView(miniLogo);row.addView(info);row.addView(prev);row.addView(play);row.addView(next);return row}

    private fun connectPlayer(){val token=SessionToken(this,ComponentName(this,RadioPlaybackService::class.java));controllerFuture=MediaController.Builder(this,token).buildAsync();controllerFuture?.addListener({try{controller=controllerFuture?.get();controller?.addListener(object:androidx.media3.common.Player.Listener{private fun refresh(){if(isFinishing||isDestroyed)return;val p=controller?:return;val playing=p.isPlaying;play.setImageResource(if(playing)R.drawable.ic_pause else R.drawable.ic_play);spectrum.setPlaying(playing);status.text=when{p.playbackState==androidx.media3.common.Player.STATE_BUFFERING->"Bağlanıyor...";playing->if(nowPlaying.isNotBlank())nowPlaying else "CANLI • "+title.text;p.playbackState==androidx.media3.common.Player.STATE_READY->"Durduruldu";else->"Hazır"};liveBadge.text=when{playing->"● CANLI";p.playbackState==androidx.media3.common.Player.STATE_BUFFERING->"BAĞLANIYOR";else->"RADYO"};liveBadge.setTextColor(if(playing||p.playbackState==androidx.media3.common.Player.STATE_BUFFERING)orange else muted)};override fun onIsPlayingChanged(isPlaying:Boolean)=refresh();override fun onPlaybackStateChanged(playbackState:Int)=refresh();override fun onMediaItemTransition(item:MediaItem?,reason:Int){title.text=item?.mediaMetadata?.title?:"Bir radyo seç";syncCurrentStation();refresh()};override fun onMetadata(metadata:Metadata){for(i in 0 until metadata.length()){(metadata.get(i)as?IcyInfo)?.title?.trim()?.takeIf{it.isNotBlank()}?.let{raw->nowPlaying=formatNowPlaying(raw);if(!isFinishing&&!isDestroyed)status.text=nowPlaying}}};override fun onPlayerError(error:androidx.media3.common.PlaybackException){nowPlaying="";if(!isFinishing&&!isDestroyed){status.text="Yayın açılamadı";spectrum.setPlaying(false);liveBadge.text="RADYO";liveBadge.setTextColor(muted)}}});syncCurrentStation()}catch(_:Exception){if(!isFinishing&&!isDestroyed)status.text="Oynatıcı başlatılamadı"}},ContextCompat.getMainExecutor(this))}
    private fun syncCurrentStation(){val p=controller?:return;val item=p.currentMediaItem?:return;val index=stations.indexOfFirst{it.resolvedUrl==item.mediaId};if(index>=0){currentIndex=index;title.text=stations[index].name;miniLogo.bind(stations[index].name,stations[index].genre)};play.setImageResource(if(p.isPlaying)R.drawable.ic_pause else R.drawable.ic_play);spectrum.setPlaying(p.isPlaying)}
    private fun togglePlay(){controller?.let{if(it.isPlaying)it.pause()else it.play()}}
    private fun formatNowPlaying(raw:String):String{val cleaned=raw.replace(Regex("\\s+")," ").trim();val parts=cleaned.split(Regex("\\s+[-–—/]\\s+|\\|"),limit=2);return if(parts.size==2)parts[0].trim()+" • "+parts[1].trim()else cleaned}
    private fun playRelative(delta:Int){if(stations.isEmpty())return;currentIndex=if(currentIndex<0)0 else(currentIndex+delta+stations.size)%stations.size;play(stations[currentIndex])}
    private fun play(station:Station){if(isFinishing||isDestroyed)return;rememberStation(station);currentIndex=stations.indexOfFirst{it.resolvedUrl==station.resolvedUrl}.coerceAtLeast(0);val metadata=androidx.media3.common.MediaMetadata.Builder().setTitle(station.name).setArtist("Keyfe Keder Radyo").setAlbumTitle("Canlı Yayın").setArtworkUri(Uri.parse("android.resource://$packageName/drawable/station_artwork_default")).build();val item=MediaItem.Builder().setMediaId(station.resolvedUrl).setUri(station.resolvedUrl).setMediaMetadata(metadata).build();try{controller?.setMediaItem(item);controller?.prepare();controller?.play()}catch(_:Exception){status.text="Yayın başlatılamadı";return};title.text=station.name;nowPlaying="";status.text="Bağlanıyor...";liveBadge.text="BAĞLANIYOR";liveBadge.setTextColor(orange);miniLogo.bind(station.name,station.genre)}
    private fun filter(query:String){val q=query.trim();val list=if(q.isBlank())stations else stations.filter{it.name.contains(q,true)||it.genre.contains(q,true)||it.country.contains(q,true)||it.language.contains(q,true)};if(selectedNav==0){showRadios(list);selectNav(1)}else adapter.submitList(list)}
    private fun loadStations(){executor.execute{try{val loaded=StationRepository().load();runOnUiThread{if(isFinishing||isDestroyed)return@runOnUiThread;stations=loaded;adapter.submitList(loaded);if(selectedNav==0)buildHome();syncCurrentStation()}}catch(_:Exception){runOnUiThread{if(!isFinishing&&!isDestroyed)status.text="Radyolar yüklenemedi"}}}}
    private fun historyStations():List<Station>{val urls=prefs.getString("history","").orEmpty().split("|").filter{it.isNotBlank()};return urls.mapNotNull{url->stations.firstOrNull{it.resolvedUrl==url}}.take(10)}
    private fun rememberStation(station:Station){val urls=prefs.getString("history","").orEmpty().split("|").filter{it.isNotBlank()&&it!=station.resolvedUrl}.toMutableList();urls.add(0,station.resolvedUrl);prefs.edit().putString("history",urls.take(12).joinToString("|")).apply()}
    private fun isFavorite(station:Station)=prefs.getBoolean(station.resolvedUrl,false)
    private fun toggleFavorite(station:Station){prefs.edit().putBoolean(station.resolvedUrl,!isFavorite(station)).apply();adapter.notifyDataSetChanged();if(selectedNav==0)buildHome();if(selectedNav==3)showRadios(stations.filter{isFavorite(it)})}
    private fun showExitDialog(){val playing=controller?.isPlaying==true;if(!playing){finishAndRemoveTask();return};val dialog=android.app.AlertDialog.Builder(this).setTitle("Keyfe Keder Radyo").setMessage("Uygulamadan çıkmak istiyor musun?\n\nArka planda çalmaya devam edebilirim veya yayını tamamen kapatabilirim.").setPositiveButton("Arka planda çal"){_,_->finishAndRemoveTask()}.setNegativeButton("Hayır, kapat"){_,_->stopPlaybackAndClose()}.setNeutralButton("Vazgeç",null).create();dialog.setOnShowListener{dialog.getButton(android.content.DialogInterface.BUTTON_POSITIVE)?.setTextColor(orange);dialog.getButton(android.content.DialogInterface.BUTTON_NEGATIVE)?.setTextColor(Color.rgb(255,90,90));dialog.getButton(android.content.DialogInterface.BUTTON_NEUTRAL)?.setTextColor(muted)};dialog.show()}
    private fun stopPlaybackAndClose(){try{controller?.stop();controller?.clearMediaItems()}catch(_:Exception){};try{stopService(Intent(this,RadioPlaybackService::class.java))}catch(_:Exception){};finishAndRemoveTask()}
    private fun showSettings(){val dialog=android.app.Dialog(this);val root=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(d(20),d(18),d(20),d(16));background=GradientDrawable().apply{setColor(Color.rgb(20,20,22));cornerRadius=d(28).toFloat();setStroke(d(1),Color.rgb(50,50,54))}};root.addView(TextView(this).apply{text="Ayarlar";textSize=25f;setTextColor(white);setTypeface(typeface,android.graphics.Typeface.BOLD)},LinearLayout.LayoutParams(-1,d(38)));root.addView(sectionLabel("OYNATMA"));root.addView(settingCard("🌙","Uyku zamanlayıcısı",sleepTimerLabel()){val options=arrayOf("Kapalı","15 dakika","30 dakika","45 dakika","60 dakika","90 dakika");android.app.AlertDialog.Builder(this@MainActivity).setTitle("Uyku zamanlayıcısı").setItems(options){_,which->val mins=when(which){0->0L;1->15L;2->30L;3->45L;4->60L;else->90L};prefs.edit().putLong("sleep_until",if(mins==0L)0L else System.currentTimeMillis()+mins*60_000L).apply()}.show()});root.addView(settingCard("📡","Arka planda çalma","Yayın açıkken uygulamadan çıkabilirsin"){android.widget.Toast.makeText(this,"Arka planda çalma etkin: medya servisi yayını sürdürüyor.",android.widget.Toast.LENGTH_SHORT).show()});root.addView(sectionLabel("GÖRÜNÜM"));root.addView(settingCard("✨","Akıcı animasyonlar","Kartlar ve spectrum efektleri açık",null));root.addView(settingCard("🎨","Keyfe Keder teması","Turuncu imza renk",null));root.addView(sectionLabel("UYGULAMA"));root.addView(settingCard("📻","Keyfe Keder Radyo","Android • "+BuildConfig.VERSION_NAME,null));root.addView(TextView(this).apply{text="Bir Frekans, Bin Keyif.";textSize=11f;setTextColor(orange);gravity=Gravity.CENTER;setPadding(0,d(14),0,0)});dialog.setContentView(root);dialog.window?.setBackgroundDrawableResource(android.R.color.transparent);dialog.setCanceledOnTouchOutside(true);dialog.show();dialog.window?.setLayout(-1,-2)}
    private fun sectionLabel(textValue:String)=TextView(this).apply{text=textValue;textSize=10f;setTextColor(orange);setTypeface(typeface,android.graphics.Typeface.BOLD);setPadding(d(4),d(14),d(4),d(7))}
    private fun settingCard(icon:String,name:String,detail:String,action:(()->Unit)?):View{val card=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER_VERTICAL;setPadding(d(14),d(9),d(12),d(9));background=rounded(surface2,18);isClickable=action!=null;if(action!=null)setOnClickListener{tap(this);action.invoke()}};card.addView(TextView(this).apply{text=icon;textSize=19f;gravity=Gravity.CENTER},LinearLayout.LayoutParams(d(42),d(50)));val info=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;gravity=Gravity.CENTER_VERTICAL;layoutParams=LinearLayout.LayoutParams(0,-2,1f)};info.addView(TextView(this).apply{text=name;textSize=14f;setTextColor(white);setTypeface(typeface,android.graphics.Typeface.BOLD)});info.addView(TextView(this).apply{text=detail;textSize=10f;setTextColor(muted);maxLines=1});card.addView(info);if(action!=null)card.addView(TextView(this).apply{text="›";textSize=24f;setTextColor(muted);gravity=Gravity.CENTER},LinearLayout.LayoutParams(d(24),d(50)));return card}
    private fun sleepTimerLabel():String{val until=prefs.getLong("sleep_until",0L);if(until<=System.currentTimeMillis())return "Kapalı";val mins=((until-System.currentTimeMillis())/60000L).coerceAtLeast(1L);return "Yaklaşık "+mins+" dk kaldı"}

    private fun showFullPlayer(){if(isFinishing||isDestroyed)return;val dialog=android.app.Dialog(this);dialog.window?.setDimAmount(.72f);val current=stations.getOrNull(currentIndex);val root=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;gravity=Gravity.CENTER_HORIZONTAL;setPadding(d(22),d(10),d(22),d(18));background=GradientDrawable().apply{setColor(bg);cornerRadii=floatArrayOf(d(30).toFloat(),d(30).toFloat(),d(30).toFloat(),d(30).toFloat(),0f,0f,0f,0f);setStroke(d(1),Color.rgb(48,48,51))}};val top=LinearLayout(this).apply{gravity=Gravity.CENTER_VERTICAL;layoutParams=LinearLayout.LayoutParams(-1,d(48))};val close=TextView(this).apply{text="⌄";textSize=30f;setTextColor(muted);gravity=Gravity.CENTER;setOnClickListener{tap(this);dialog.dismiss()}};top.addView(close,LinearLayout.LayoutParams(d(54),d(48)));val now=TextView(this).apply{text="ŞİMDİ ÇALIYOR";textSize=10f;setTextColor(orange);gravity=Gravity.CENTER;background=rounded(Color.rgb(43,28,20),16);setPadding(d(12),0,d(12),0)};top.addView(now,LinearLayout.LayoutParams(-2,d(30)).apply{gravity=Gravity.CENTER});top.addView(View(this),LinearLayout.LayoutParams(0,1,1f));val favorite=ImageButton(this).apply{setImageResource(R.drawable.ic_heart);setColorFilter(if(current!=null&&isFavorite(current))orange else white);setBackgroundColor(Color.TRANSPARENT);contentDescription="Favoriye ekle";setOnClickListener{current?.let{tap(this);toggleFavorite(it);setColorFilter(if(isFavorite(it))orange else white)}}};top.addView(favorite,LinearLayout.LayoutParams(d(48),d(48)));root.addView(top);val logoFrame=FrameLayout(this).apply{gravity=Gravity.CENTER;layoutParams=LinearLayout.LayoutParams(d(226),d(226)).apply{topMargin=d(8);bottomMargin=d(18)};background=GradientDrawable().apply{shape=GradientDrawable.OVAL;setColor(Color.rgb(22,22,24));setStroke(d(2),Color.rgb(77,43,24))}};val logo=StationArtworkView(this).apply{clipToOutline=true;background=GradientDrawable().apply{shape=GradientDrawable.OVAL;setColor(Color.rgb(24,24,25))};contentDescription=current?.name?:"Radyo";bind(current?.name?:"RADYO",current?.genre?:"")};logoFrame.addView(logo,FrameLayout.LayoutParams(d(210),d(210)).apply{gravity=Gravity.CENTER});root.addView(logoFrame);root.addView(TextView(this).apply{text=current?.name?:title.text;textSize=25f;setTextColor(white);gravity=Gravity.CENTER;setTypeface(typeface,android.graphics.Typeface.BOLD);maxLines=2;ellipsize=android.text.TextUtils.TruncateAt.END},LinearLayout.LayoutParams(-1,d(64)));root.addView(TextView(this).apply{text=if(controller?.isPlaying==true)"●  CANLI YAYIN"else"YAYIN HAZIR";textSize=11f;setTextColor(if(controller?.isPlaying==true)orange else muted);gravity=Gravity.CENTER;letterSpacing=.08f},LinearLayout.LayoutParams(-1,d(28)));root.addView(TextView(this).apply{text=status.text.ifBlank{"Canlı yayın"};textSize=13f;setTextColor(white);gravity=Gravity.CENTER;maxLines=1;ellipsize=android.text.TextUtils.TruncateAt.MARQUEE;isSelected=true;background=rounded(surface,20);setPadding(d(18),0,d(18),0)},LinearLayout.LayoutParams(-1,d(42)).apply{topMargin=d(4)});val bigSpectrum=AudioSpectrumView(this).apply{setPlaying(controller?.isPlaying==true)};root.addView(bigSpectrum,LinearLayout.LayoutParams(-1,d(46)).apply{topMargin=d(8);bottomMargin=d(8)});val controls=LinearLayout(this).apply{gravity=Gravity.CENTER;setPadding(0,d(4),0,0)};val previous=iconButton(R.drawable.ic_prev).apply{layoutParams=LinearLayout.LayoutParams(d(60),d(60))};val main=ImageButton(this).apply{setImageResource(if(controller?.isPlaying==true)R.drawable.ic_pause else R.drawable.ic_play);setColorFilter(white);background=GradientDrawable().apply{shape=GradientDrawable.OVAL;setColor(orange)};elevation=d(6).toFloat();contentDescription="Oynat / duraklat";layoutParams=LinearLayout.LayoutParams(d(82),d(82)).apply{setMargins(d(20),0,d(20),0)};setOnClickListener{tap(this);togglePlay();postDelayed({if(!isFinishing&&!isDestroyed&&!dialog.isShowing)return@postDelayed;setImageResource(if(controller?.isPlaying==true)R.drawable.ic_pause else R.drawable.ic_play);bigSpectrum.setPlaying(controller?.isPlaying==true)},120)}};val next=iconButton(R.drawable.ic_next).apply{layoutParams=LinearLayout.LayoutParams(d(60),d(60))};previous.setOnClickListener{tap(it);playRelative(-1);dialog.dismiss();handler.postDelayed({if(!isFinishing&&!isDestroyed)showFullPlayer()},180)};next.setOnClickListener{tap(it);playRelative(1);dialog.dismiss();handler.postDelayed({if(!isFinishing&&!isDestroyed)showFullPlayer()},180)};controls.addView(previous);controls.addView(main);controls.addView(next);root.addView(controls,LinearLayout.LayoutParams(-1,d(92)));dialog.setContentView(root);dialog.window?.setBackgroundDrawableResource(android.R.color.transparent);dialog.setCanceledOnTouchOutside(true);dialog.show();dialog.window?.setLayout(-1,(resources.displayMetrics.heightPixels*.90f).toInt())}
    private fun iconButton(resId:Int)=ImageButton(this).apply{setImageResource(resId);setBackgroundColor(Color.TRANSPARENT);setColorFilter(white);layoutParams=LinearLayout.LayoutParams(d(52),d(52))}
    private fun rounded(color:Int,radiusDp:Int)=GradientDrawable().apply{setColor(color);cornerRadius=d(radiusDp).toFloat()}
    private fun tap(view:View){view.animate().scaleX(.96f).scaleY(.96f).setDuration(70).withEndAction{view.animate().scaleX(1f).scaleY(1f).setDuration(130).start()}.start()}
    private fun d(value:Int)=(value*resources.displayMetrics.density).toInt()
    override fun onDestroy(){handler.removeCallbacksAndMessages(null);controllerFuture?.let{MediaController.releaseFuture(it)};executor.shutdownNow();super.onDestroy()}
}
